from pathlib import Path
for name in ['compose.yaml','package.json','package_network.py','README.md','DEPLOY.md']:
 f=Path(name);f.write_text(f.read_text(encoding='utf-8-sig').replace('7.0.0','7.1.0'),encoding='utf-8')
f=Path('NETWORK.md');s=f.read_text(encoding='utf-8');s+='''\n\n## 7.1.0 — редактируемая горловина и пояснения параметров\n\nГорловина редактируется наравне с рабочей частью и общей высотой. Изменение горловины сохраняет рабочую часть и толщины плит, пересчитывает общую высоту и глубину. Изменение общей высоты или рабочей части пересчитывает горловину. Нулевой высоты горловины достаточно для модели без неё; отрицательная не допускается. Редактирование отметки пола также сохраняет рабочую часть. Эти действия явные и входят в отмену/повтор; открытие старых схем не меняет их параметры.\n\nВ правой панели дан кликабельный разрез колодца: горловина, рабочая часть, верхняя плита, днище. Нажатие открывает нужную группу и переводит фокус в поле. Параметры плит названы как толщины, поясняют влияние на горловину и габариты выемки. Поворот колодца показан видом сверху. Зазор и откос котлована объясняются на отдельной схеме, обновляющейся при вводе.\n\nWeb 7.1.0 + прежний API 2.2.0. Новых полей модели или миграций БД нет.\n''';f.write_text(s,encoding='utf-8')
